SIZE = 768

screen = turtle.Screen()
screen.setup(int(SIZE*SCALE)+40, int(SIZE*SCALE)+40)
screen.title("Maths heart")
screen.bgcolor(PAPER)
screen.tracer(0)
t = turtle.Turtle(visible=False)
t.speed(0)
t.pensize(1)
count = 0

def tick(n=STEP, delay=DELAY):
    global count
    count += 1
    if count % n == 0:
        screen.update(); time.sleep(delay)

def gray(lo, hi):
    g = random.randint(lo, hi)
    return "#%02x%02x%02x" % (g, g, min(255, g + 6))

def draw_grid():
    t.pencolor(GRID); t.pensize(1)
    half = SIZE / 2 * SCALE
    step = 25.6 * SCALE
    k = 0
    x = (12 - SIZE/2) * SCALE
    while x < half:
        t.penup(); t.goto(x, -half); t.pendown(); t.goto(x, half)
        x += step; k += 1
        if k % 2 == 0: screen.update(); time.sleep(0.01)
    y = (SIZE/2 - 12) * SCALE
    while y > -half:
        t.penup(); t.goto(-half, y); t.pendown(); t.goto(half, y)
        y -= step; k += 1
        if k % 2 == 0: screen.update(); time.sleep(0.01)
    t.penup()

def resample(pts, gap=4.0):
    out = [pts[0]]
    for (x1, y1), (x2, y2) in zip(pts, pts[1:]):
        d = math.hypot(x2-x1, y2-y1)
        n = max(1, int(d // gap))
        for i in range(1, n + 1):
            f = i / n
            out.append((x1 + (x2-x1)*f, y1 + (y2-y1)*f))
    return out

def wobble(pts, big, small):
    dx = dy = 0.0
    res = []
    for x, y in pts:
        dx = dx*0.9 + random.uniform(-big, big)
        dy = dy*0.9 + random.uniform(-big, big)
        res.append((x + dx + random.uniform(-small, small),
                    y + dy + random.uniform(-small, small)))
    return res

def stroke_path(path, big, small, lo, hi, widths):
    pts = resample([(x*SCALE, y*SCALE) for x, y in path], 4.0)
    if len(pts) < 2:
        return
    pts = wobble(pts, big, small)
    i = 0
    t.penup(); t.goto(pts[0]); t.pendown()
    while i < len(pts) - 1:
        t.pencolor(gray(lo, hi))
        t.pensize(random.choice(widths))
        for p in pts[i+1:i+9]:
            t.goto(p); tick()
        i += 8
    t.penup()

def order_key(p):
    cx = sum(q[0] for q in p) / len(p)
    cy = sum(q[1] for q in p) / len(p)
    return (int(-cy // 50), cx)
ORDERED = sorted(PATHS, key=order_key)

def full_pass(big, small, lo, hi, widths):
    for p in ORDERED:
        stroke_path(p, big, small, lo, hi, widths)

draw_grid()
full_pass(0.30, 0.45, 175, 205, (2,))
screen.update()
print("")
screen.exitonclick()